const AI_TIMEOUT_MS = 45_000
const cacheRef = useRef(new Map())

function cacheKey(task, prompt) {
  let hash = 0
  for (let i = 0; i < prompt.length; i++) {
    hash = ((hash << 5) - hash) + prompt.charCodeAt(i)
    hash |= 0
  }
  return `${task}:${hash}`
}

function safeParseJSON(raw, fallback = null) {
