async function callAI(prompt, systemPrompt, task) {
  const key = cacheKey(task, prompt)
  const cached = cacheRef.current.get(key)
  if (cached) return cached

  const controller = new AbortController()
  const id = setTimeout(() => controller.abort(), AI_TIMEOUT_MS)
  try {
    const token = await getAccessToken()
    const res = await fetch('/api/ai', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        ...(token ? { Authorization: `Bearer ${token}` } : {}),
      },
      body: JSON.stringify({ prompt, systemPrompt, task }),
      signal: controller.signal,
    })
    clearTimeout(id)
    const data = await res.json().catch(() => ({}))
    if (!res.ok) {
      const msg = data.error || `Error ${res.status}`
      if (msg.includes('Límite') || msg.includes('429')) throw new Error(msg)
      throw new Error('Error de conexión con la IA. Intenta de nuevo.')
    }
    cacheRef.current.set(key, data.text)
